def _kuz(nome, extra_cosa, forza_extra):
    return {
        "cosa_fa": f"{nome} è una rete neurale convoluzionale (CNN) progettata dal prof. Kuznetsov per distinguere volti reali da attacchi di presentazione. Riceve il volto a 256×256 pixel dopo il preprocessing del suo dataset e produce due probabilità: bona fide / attacco. {extra_cosa}",
        "quando_funziona": ["Foto stampate e replay su schermo simili a quelli visti in addestramento (intra-dataset: 99,7–99,9% di accuracy nel paper).",
                            "Immagini nitide, volto frontale, illuminazione simile al training."] + forza_extra,
        "limiti": ["Ogni variante è addestrata su un solo dataset pubblico (NUAA, CASIA-FASD, CelebA-Spoof o il sintetico SynthASpoof) con lo script della tesi; le versioni 'split 80/20 del docente' non vanno valutate sul proprio dataset perché ne hanno visto anche il test.",
                   "Generalizza male a dataset diversi: nel paper del docente ~52% di accuracy media in cross-dataset con training su un solo dataset.",
                   "Non vede il tempo: nessun indizio da movimento o battito di ciglia."],
        "esempi": [{"titolo": "Foto stampata", "testo": "La rete impara la grana della stampa e la perdita di dettaglio: con pesi addestrati, la mappa Grad-CAM si accende sulle zone di pelle piatta."},
                   {"titolo": "Replay su smartphone", "testo": "Il pattern periodico dei pixel e i riflessi dello schermo attivano i filtri del primo blocco convoluzionale."},
                   {"titolo": "Maschera 3D (3DMAD)", "testo": "La maschera ha rilievo ma texture rigida e senza pori: i filtri ad alta frequenza rispondono in modo diverso dalla pelle."}],
        "passi": _KUZNETSOV_PASSI,
        "riferimenti": _KUZ_RIF,
    }


